from gurobipy import Model, GRB, quicksum

def build_and_solve():
    cost_records = [r for r in LEGACY_RECORDS if r['source'].endswith('transportation_costs.csv')]
    if not cost_records:
        raise ValueError('No transportation_costs.csv records found in LEGACY_RECORDS')
    supply_ids = [r['values']['Unnamed: 0'] for r in cost_records]
    demand_ids = [k for k in cost_records[0]['values'] if k != 'Unnamed: 0']
    cost = {}
    for r in cost_records:
        s = r['values']['Unnamed: 0']
        for d in demand_ids:
            try:
                cost[s, d] = float(r['values'][d])
            except Exception:
                raise ValueError(f'Missing or invalid cost for ({s},{d})')
    supply_capacity_map = {'supply1': 60, 'supply2': 22, 'supply3': 16, 'supply4': 14, 'supply5': 19, 'supply6': 70, 'supply7': 60, 'supply8': 39}
    demand_map = {'demand1': 9, 'demand2': 66, 'demand3': 56, 'demand4': 17, 'demand5': 43, 'demand6': 62, 'demand7': 10, 'demand8': 37}
    if set(supply_ids) != set(supply_capacity_map):
        raise ValueError('Supply ids in cost matrix and supply_capacity do not match')
    if set(demand_ids) != set(demand_map):
        raise ValueError('Demand ids in cost matrix and customer_demand do not match')
    for s in supply_ids:
        for d in demand_ids:
            if (s, d) not in cost:
                raise ValueError(f'Missing cost for ({s},{d})')
    m = Model()
    m.Params.MIPGap = 0.0001
    x_vars = m.addVars(supply_ids, demand_ids, lb=0, vtype=GRB.CONTINUOUS, name='')
    m.setObjective(quicksum((cost[s, d] * x_vars[s, d] for s in supply_ids for d in demand_ids)), GRB.MINIMIZE)
    for d in demand_ids:
        m.addConstr(quicksum((x_vars[s, d] for s in supply_ids)) == demand_map[d], name='')
    for s in supply_ids:
        m.addConstr(quicksum((x_vars[s, d] for d in demand_ids)) <= supply_capacity_map[s], name='')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(m.ObjVal)
        for s in supply_ids:
            for d in demand_ids:
                v = x_vars[s, d]
                print(f'{v.VarName} {v.X}')
    else:
        print(m.Status)
    return m
m = build_and_solve()